<template><div class="auth-single"><form class="fm-card reset" @submit.prevent="submit"><span class="fm-kicker">找回账户</span><h1>设置新密码</h1><p class="muted">重置链接 30 分钟内有效，使用后会立即失效。</p><label class="field"><span>新密码</span><input v-model="password" type="password" minlength="6" required autofocus/></label><div v-if="message" class="notice" :class="{error:failed,ok:!failed}">{{message}}</div><FmButton variant="primary" type="submit" :loading="busy">更新密码</FmButton><RouterLink class="back" to="/">返回登录</RouterLink></form></div></template>
<script setup>import{ref}from"vue";import{useRoute}from"vue-router";import{api,toast}from"../api/client.js";import FmButton from"../ui/freemodel/components/FmButton.vue";const route=useRoute(),password=ref(""),message=ref(""),failed=ref(false),busy=ref(false);async function submit(){busy.value=true;try{const v=await api("/api/auth/reset",{method:"POST",body:JSON.stringify({token:String(route.query.token||""),password:password.value})});message.value=v.message;failed.value=false;toast(v.message,"success")}catch(e){message.value=e.message;failed.value=true;toast(e.message,"error")}finally{busy.value=false}}</script><style scoped>.auth-single{display:grid;min-height:100vh;place-items:center;padding:20px}.reset{width:min(430px,100%);padding:30px}.reset h1{margin:8px 0}.reset>.button{width:100%}.back{display:block;margin-top:14px;color:var(--fm-ink-muted);font-size:12px;text-align:center}</style>
